import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {mkdtemp,rm} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import test,{after,before} from 'node:test';
import type {FastifyInstance,LightMyRequestResponse} from 'fastify';
import {buildApp} from './app.ts';
import {AiCredentialVault} from './ai/credential-vault.ts';
import {CalendarService,scheduleHomeAssistantStartupSync,type CalendarEvent,type CalendarInfo,type CalendarPage,type CalendarProvider,type CalendarTokenSet,type CalendarTransport} from './calendar/service.ts';
import {CalendarProviderConfigurationService} from './calendar/provider-config.ts';
import type {HomeAssistantTemperatureCandidate,HomeAssistantTemperatureObservation} from './calendar/home-assistant-client.ts';
