test('Microsoft registration remains installation-admin-only, CSRF-bound, bounded and durable across an API restart',async()=>{
  const managerCreated=await app.inject({method:'POST',url:`/api/v1/households/${householdId}/people`,headers:headers(ownerCookie,ownerCsrf),payload:{displayName:'Synthetic Household Calendar Manager',ageGroup:'adult',rolePreset:'household_admin',displayIds:[],login:{email:'calendar-household-manager@test.invalid',password:'Synthetic-manager-password-42',locale:'nb',theme:'system'}}});
  assert.equal(managerCreated.statusCode,201,managerCreated.body);
  const manager=await login('calendar-household-manager@test.invalid','Synthetic-manager-password-42');
  const endpoint=`/api/v1/installations/${installationId}/calendar-providers/microsoft`;
  const payload={expectedRevision:0,status:'active' as const,clientId:'synthetic-microsoft-database-client',clientSecret:'synthetic-microsoft-database-secret',tenant:'organizations'};
  const managerRead=await app.inject({method:'GET',url:`/api/v1/installations/${installationId}/calendar-providers`,headers:{cookie:manager.cookie}});
  assert.equal(managerRead.statusCode,403,'a household administrator cannot read installation registration status: '+managerRead.body);
  const managerWrite=await app.inject({method:'PUT',url:endpoint,headers:headers(manager.cookie,manager.csrf),payload});
  assert.equal(managerWrite.statusCode,403,'a household administrator cannot configure provider credentials: '+managerWrite.body);
  const missingCsrf=await app.inject({method:'PUT',url:endpoint,headers:{cookie:ownerCookie,origin:'https://samvev.test.invalid'},payload});
  assert.equal(missingCsrf.statusCode,403,'configuration writes require the initiating session CSRF token: '+missingCsrf.body);
  const oversized=await app.inject({method:'PUT',url:endpoint,headers:headers(ownerCookie,ownerCsrf),payload:{...payload,clientSecret:'x'.repeat(17_000)}});
  assert.equal(oversized.statusCode,413,'registration upload body limit rejects oversized secrets before persistence: '+oversized.body);
  const configured=await app.inject({method:'PUT',url:endpoint,headers:headers(ownerCookie,ownerCsrf),payload});
  assert.equal(configured.statusCode,200,configured.body);
  const first= configured.json().providers.microsoft;
  assert.deepEqual({state:first.state,source:first.source,tenant:first.tenant,revision:first.revision},{state:'configured',source:'database',tenant:'organizations',revision:1});
  assert.equal(JSON.stringify(configured.json()).includes(payload.clientSecret),false,'responses never return Microsoft client secrets');
  const persisted=(await pool.query<{config_ciphertext:string}>('SELECT config_ciphertext FROM installation_calendar_provider_configs WHERE installation_id=$1 AND provider=\'microsoft\'',[installationId])).rows[0]!;
  assert.equal(persisted.config_ciphertext.includes(payload.clientSecret),false,'the database stores encrypted configuration instead of the client secret');
  await app.close();
  app=await buildApp({calendarTransport:new SyntheticTransport(),aiKeyFile:join(keyDirectory,'key'),runtimeConfig:{publicOrigin:'https://samvev.test.invalid',secureCookies:true,trustProxy:false}});
  const restarted=await app.inject({method:'GET',url:`/api/v1/installations/${installationId}/calendar-providers`,headers:{cookie:ownerCookie}});
  assert.equal(restarted.statusCode,200,restarted.body);
  const afterRestart=restarted.json().providers.microsoft;
  assert.deepEqual({state:afterRestart.state,source:afterRestart.source,tenant:afterRestart.tenant,revision:afterRestart.revision},{state:'configured',source:'database',tenant:'organizations',revision:1},'the restarted API reads the same installation-scoped registration');
  assert.equal(JSON.stringify(restarted.json()).includes(payload.clientSecret),false);
});

test('provider configuration commit rechecks the initiating session after a concurrent revocation',async()=>{
  const owner=(await pool.query<{account_id:string;membership_id:string;household_id:string;capabilities:string[]}>(`SELECT membership.account_id,membership.id membership_id,membership.household_id,membership.capabilities FROM memberships membership JOIN accounts account ON account.id=membership.account_id WHERE account.email_normalized='calendar-owner@test.invalid'`)).rows[0]!;
  const session=(await pool.query<{id:string}>(`INSERT INTO sessions(account_id,token_hash,csrf_hash,expires_at) VALUES($1,encode(gen_random_bytes(32),'hex'),encode(gen_random_bytes(32),'hex'),clock_timestamp()+interval '1 hour') RETURNING id`,[owner.account_id])).rows[0]!;
  let encrypted!:()=>void;const encryptionReached=new Promise<void>((resolve)=>{encrypted=resolve;});
  class SignallingVault extends AiCredentialVault{override async encrypt(aad:string,value:string){const result=await super.encrypt(aad,value);encrypted();return result;}}
  const service=new CalendarProviderConfigurationService(new SignallingVault(join(keyDirectory,'key')));
  const blocker=await pool.connect();await blocker.query('BEGIN');await blocker.query('SELECT id FROM installations WHERE id=$1 FOR UPDATE',[installationId]);
  const update=service.update({installationId,householdId:owner.household_id,accountId:owner.account_id,sessionId:session.id,membershipId:owner.membership_id,capabilities:owner.capabilities},'microsoft',{expectedRevision:1,status:'active',clientId:'must-not-commit',clientSecret:'must-not-be-retained',tenant:'organizations'},'https://samvev.test.invalid');
  await encryptionReached;await pool.query('UPDATE sessions SET revoked_at=clock_timestamp() WHERE id=$1',[session.id]);await blocker.query('COMMIT');blocker.release();
  await assert.rejects(update,(error:any)=>error?.code==='FORBIDDEN');
  const unchanged=(await pool.query<{revision:number;client_id_hash:string}>('SELECT revision,client_id_hash FROM installation_calendar_provider_configs WHERE installation_id=$1 AND provider=\'microsoft\'',[installationId])).rows[0]!;
  assert.equal(unchanged.revision,1);assert.notEqual(unchanged.client_id_hash,createHash('sha256').update('must-not-commit').digest('hex'),'a revoked initiating session cannot win the configuration race');
});

test('Microsoft client replacement creates an explicit new binding without copying source ACLs',async()=>{
  const original=await connect({cookie:ownerCookie,csrf:ownerCsrf},'microsoft','Synthetic Outlook before app replacement');const changed=await app.inject({method:'PUT',url:`/api/v1/installations/${installationId}/calendar-providers/microsoft`,headers:headers(ownerCookie,ownerCsrf),payload:{expectedRevision:1,status:'active',clientId:'synthetic-microsoft-replacement-client',clientSecret:'synthetic-microsoft-replacement-secret',tenant:'organizations'}});assert.equal(changed.statusCode,200,changed.body);const old=(await app.inject({method:'GET',url:`/api/v1/households/${householdId}/calendar-connections`,headers:{cookie:ownerCookie}})).json().connections.find((item:{id:string})=>item.id===original.id);assert.equal(old.state,'expired');assert.equal(old.replacementRequired,true);assert.ok(old.sources.length>0,'old source history remains attached to the old binding');
  const replacement=await connect({cookie:ownerCookie,csrf:ownerCsrf},'microsoft','Synthetic explicit Outlook replacement',original.id);assert.equal(replacement.connection.replacesConnectionId,original.id);assert.equal(replacement.connection.replacementRequired,false);assert.ok(replacement.connection.sources.length>0);for(const source of replacement.connection.sources){assert.equal(source.enabled,false);assert.deepEqual(source.appliesTo,{household:false,personIds:[]});assert.deepEqual(source.visibility,{household:false,personIds:[],displayIds:[]});}assert.equal((await pool.query('SELECT state,disconnected_at IS NOT NULL disconnected,provider_subject_hash IS NOT NULL binding_retained FROM calendar_connections WHERE id=$1',[original.id])).rows[0].state,'disconnected');assert.equal((await pool.query('SELECT provider_subject_hash IS NOT NULL binding_retained FROM calendar_connections WHERE id=$1',[original.id])).rows[0].binding_retained,true,'replacement retains old binding/history while withdrawing its projection');
});

test('full ICS subscription URL is manager-only, encrypted at rest and revision-fenced',async()=>{
  const memberCreated=await app.inject({method:'POST',url:`/api/v1/households/${householdId}/people`,headers:headers(ownerCookie,ownerCsrf),payload:{displayName:'Synthetic ICS Owner',ageGroup:'adult',rolePreset:'member',displayIds:[],login:{email:'calendar-ics-owner@test.invalid',password:'Synthetic-ics-owner-password-42',locale:'nb',theme:'system'}}});
  assert.equal(memberCreated.statusCode,201,memberCreated.body);
  const member=await login('calendar-ics-owner@test.invalid','Synthetic-ics-owner-password-42');
  const originalUrl='webcal://calendar.synthetic.invalid/private/feed.ics?token=synthetic-original-secret';
  const created=await app.inject({method:'POST',url:`/api/v1/households/${householdId}/calendar-connections`,headers:headers(member.cookie,member.csrf),payload:{provider:'ics',name:'Synthetic private calendar',icsUrl:originalUrl}});
  assert.equal(created.statusCode,201,created.body);const connection=created.json().connection;assert.equal(JSON.stringify(created.json()).includes('synthetic-original-secret'),false);
  const stored=(await pool.query<{credential_ciphertext:string;revision:number;sync_generation:number}>('SELECT credential_ciphertext,revision,sync_generation FROM calendar_connections WHERE id=$1',[connection.id])).rows[0]!;
  assert.equal(stored.credential_ciphertext.includes('synthetic-original-secret'),false,'the database persists ciphertext rather than the subscription URL');
  const memberList=await app.inject({method:'GET',url:`/api/v1/households/${householdId}/calendar-connections`,headers:{cookie:member.cookie}});
  const managerList=await app.inject({method:'GET',url:`/api/v1/households/${householdId}/calendar-connections`,headers:{cookie:ownerCookie}});
  assert.equal(JSON.stringify(memberList.json()).includes('synthetic-original-secret'),false);assert.equal(JSON.stringify(managerList.json()).includes('synthetic-original-secret'),false);
  const secretPath=`/api/v1/households/${householdId}/calendar-connections/${connection.id}/ics-subscription`;
  assert.equal((await app.inject({method:'GET',url:secretPath,headers:{cookie:member.cookie}})).statusCode,403,'connection ownership does not grant access to the plaintext subscription address');
  const beforeDeniedWrite=(await pool.query<{revision:number;credential_ciphertext:string}>('SELECT revision,credential_ciphertext FROM calendar_connections WHERE id=$1',[connection.id])).rows[0]!;
  const deniedWrite=await app.inject({method:'PATCH',url:secretPath,headers:headers(member.cookie,member.csrf),payload:{expectedRevision:connection.revision,icsUrl:'webcal://calendar.synthetic.invalid/attempted.ics?token=must-not-write'}});
  assert.equal(deniedWrite.statusCode,403,'connection ownership does not grant permission to replace the subscription address');
  const afterDeniedWrite=(await pool.query<{revision:number;credential_ciphertext:string}>('SELECT revision,credential_ciphertext FROM calendar_connections WHERE id=$1',[connection.id])).rows[0]!;assert.deepEqual(afterDeniedWrite,beforeDeniedWrite,'a denied member write leaves the URL and revision unchanged');
  const ownerSessionValue=ownerCookie.split(';').map(value=>value.trim()).find(value=>value.startsWith('samvev_session='))?.slice('samvev_session='.length);assert.ok(ownerSessionValue);
  const ownerSession=(await pool.query<{id:string}>('SELECT id FROM sessions WHERE token_hash=$1',[createHash('sha256').update(ownerSessionValue!).digest('hex')])).rows[0]!;
  const originalDecrypt=AiCredentialVault.prototype.decrypt;let decryptStarted!:()=>void,releaseDecrypt!:()=>void;const reachedDecrypt=new Promise<void>((resolve)=>{decryptStarted=resolve;}),heldDecrypt=new Promise<void>((resolve)=>{releaseDecrypt=resolve;});
  AiCredentialVault.prototype.decrypt=async function(householdId:string,encoded:string){if(encoded===stored.credential_ciphertext){decryptStarted();await heldDecrypt;}return originalDecrypt.call(this,householdId,encoded);};
  let revokedRead:LightMyRequestResponse;
  try{const pending=app.inject({method:'GET',url:secretPath,headers:{cookie:ownerCookie}});await reachedDecrypt;await pool.query('UPDATE sessions SET revoked_at=clock_timestamp() WHERE id=$1',[ownerSession.id]);releaseDecrypt();revokedRead=await pending;}finally{releaseDecrypt();AiCredentialVault.prototype.decrypt=originalDecrypt;await pool.query('UPDATE sessions SET revoked_at=NULL WHERE id=$1',[ownerSession.id]);}
  assert.equal(revokedRead!.statusCode,409,'a session revoked while decrypting cannot receive the URL');assert.equal(JSON.stringify(revokedRead!.json()).includes('synthetic-original-secret'),false);
  const secret=await app.inject({method:'GET',url:secretPath,headers:{cookie:ownerCookie}});
  assert.equal(secret.statusCode,200,secret.body);assert.equal(secret.json().icsUrl,'https://calendar.synthetic.invalid/private/feed.ics?token=synthetic-original-secret');assert.match(String(secret.headers['cache-control']),/no-store/);assert.equal(secret.headers['referrer-policy'],'no-referrer');
  const displayToken='synthetic-calendar-url-display-token';await pool.query(`INSERT INTO displays(household_id,name,locale,theme,privacy_mode,external_items_enabled,credential_hash,credential_expires_at) VALUES($1,'Synthetic ICS URL display','nb','light',false,true,$2,clock_timestamp()+interval '1 hour')`,[householdId,createHash('sha256').update(displayToken).digest('hex')]);
  const displayOnly=await app.inject({method:'GET',url:secretPath,headers:{cookie:`samvev_display=${displayToken}`}});assert.notEqual(displayOnly.statusCode,200,'a valid paired display credential cannot use the household plaintext-secret route');
  const changedUrl='webcal://calendar.synthetic.invalid/private/next.ics?token=synthetic-updated-secret';
  const changed=await app.inject({method:'PATCH',url:secretPath,headers:headers(ownerCookie,ownerCsrf),payload:{expectedRevision:connection.revision,icsUrl:changedUrl}});
  assert.equal(changed.statusCode,200,changed.body);assert.equal(changed.json().revision,connection.revision+1);assert.equal(JSON.stringify(changed.json()).includes('synthetic-updated-secret'),false);
  const stale=await app.inject({method:'PATCH',url:secretPath,headers:headers(ownerCookie,ownerCsrf),payload:{expectedRevision:connection.revision,icsUrl:originalUrl}});assert.equal(stale.statusCode,409,'an older form cannot overwrite a newer secret URL');
  const updated=(await pool.query<{revision:number;sync_generation:number;last_error_code:string;credential_ciphertext:string}>('SELECT revision,sync_generation,last_error_code,credential_ciphertext FROM calendar_connections WHERE id=$1',[connection.id])).rows[0]!;
  assert.equal(updated.revision,connection.revision+1);assert.equal(updated.sync_generation,stored.sync_generation+1);assert.equal(updated.last_error_code,'CALENDAR_ICS_URL_CHANGED');assert.equal(updated.credential_ciphertext.includes('synthetic-updated-secret'),false);
  assert.equal((await app.inject({method:'GET',url:secretPath,headers:{cookie:member.cookie}})).statusCode,403);
});
